def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    strong_prev_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    strong_prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev_bids) if strong_prev_bids else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply >= 24:
        urgency += 1
    elif supply <= 17:
        urgency -= 1

    if strong_high >= 160:
        market = 'very_high'
    elif strong_high >= 145:
        market = 'high'
    elif strong_high >= 100:
        market = 'medium'
    else:
        market = 'low'

    if urgency <= 0:
        bid = 8.0 if market in ('very_high', 'high') else 18.0
    elif urgency == 1:
        if market == 'very_high':
            bid = 18.0
        elif market == 'high':
            bid = 32.0
        else:
            bid = max(28.0, strong_high * 0.45)
    elif urgency == 2:
        if market == 'very_high':
            bid = max(42.0, strong_high * 0.38)
        elif market == 'high':
            bid = max(58.0, strong_high * 0.48)
        else:
            bid = max(46.0, strong_high + 3.0)
    elif urgency == 3:
        if market == 'very_high':
            bid = max(78.0, strong_high * 0.62)
        elif market == 'high':
            bid = max(92.0, strong_high * 0.7)
        else:
            bid = max(70.0, strong_high + 6.0)
    else:
        if market == 'very_high':
            bid = max(118.0, strong_high + 2.0)
        elif market == 'high':
            bid = max(108.0, strong_high + 4.0)
        else:
            bid = max(88.0, strong_high + 8.0)

    if supply >= 24 and urgency >= 2:
        bid += 8.0
    if supply <= 16 and urgency <= 2:
        bid *= 0.75

    max_safe = budget
    if hp > 5 and no_water_days == 0:
        max_safe = min(max_safe, budget * 0.55)
    elif hp > 3:
        max_safe = min(max_safe, budget * 0.75)

    bid = min(bid, max_safe)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Immediate reaction to yesterday bids (only previous_trace)
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(int(prev['hp_after']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: if supply is closer to MIN_SUPPLY, water is scarcer.
    # Map to [0,1] where 0=abundant, 1=scarce.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    # Determine base aggressiveness
    # If opponent bids were extremely high, competition is already intense.
    extreme_competition = highest_prev_bid >= DAILY_SALARY * 1.6  # ~144

    # If my hp is low or I have already missed water days, I must secure allocation.
    urgent = (my_hp <= 2) or (my_no_water_days >= 2)

    # Target bid logic
    if urgent:
        # Push near top-of-market but still cap by budget.
        target = DAILY_SALARY * (0.95 + 0.15 * scarcity)
    else:
        if extreme_competition:
            # Bid high enough to not be outcompeted, but undercut slightly.
            # Use avg as anchor and add small premium based on scarcity.
            anchor = avg_prev_bid if avg_prev_bid > 0 else highest_prev_bid
            target = min(anchor + 5.0 * (0.5 + scarcity), DAILY_SALARY * (1.75 + 0.1 * scarcity))
        else:
            # Moderate bid; increase with scarcity.
            target = DAILY_SALARY * (0.55 + 0.35 * scarcity)

    # Convert target to final bid within budget and reasonable bounds.
    # Also avoid bidding above what seems like typical high bids by too much.
    max_reasonable = DAILY_SALARY * 2.0
    target = min(target, max_reasonable)

    final_bid = min(my_budget, target)

    # If budget is tiny, still bid something consistent to possibly win.
    if final_bid <= 0.0:
        final_bid = min(my_budget, DAILY_SALARY * 0.1)

    # Ensure non-negative float
    if final_bid < 0.0:
        final_bid = 0.0

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    supply = day_context['supply']
    day = day_context['day']
    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.85:
            # Opponents aggressive; if I'm healthy, bid low to save budget; if weak, bid higher
            if hp > 4:
                bid = min(budget, DAILY_SALARY * 0.35)
            else:
                bid = min(budget, DAILY_SALARY * 0.9)
        else:
            # Moderate opponents; try to beat highest by small margin, but cap at 90% salary
            target = max(DAILY_SALARY * 0.45, highest_prev + 1)
            bid = min(budget, target)
    else:
        # No info, default
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.4)

    # Ensure bid is within 0 and budget, and not exceed budget
    bid = max(0, min(budget, bid))
    return bid
